<?php use App\Core\Session; ?>
<div class="row"><div class="col-lg-5 mb-4"><div class="card shadow-sm"><div class="card-body"><h1 class="h5">Thêm danh mục</h1><form method="post" action="<?= e(url('/admin/categories')) ?>"><input type="hidden" name="_token" value="<?= e(Session::csrfToken()) ?>"><div class="form-group"><label>Tên danh mục</label><input class="form-control" name="name" maxlength="100" required></div><div class="form-group"><label>Mô tả</label><textarea class="form-control" name="description" rows="3"></textarea></div><button class="btn btn-primary">Thêm danh mục</button></form></div></div></div><div class="col-lg-7 mb-4"><div class="card shadow-sm"><div class="table-responsive"><table class="table mb-0"><thead class="thead-light"><tr><th>Danh mục</th><th>Slug</th><th>Trạng thái</th><th></th></tr></thead><tbody><?php foreach($categories as $c):?><tr><td><span class="badge-soft <?= e(category_badge_class((string)$c['name'])) ?>"><?= e((string)$c['name']) ?></span></td><td><code><?= e((string)$c['slug']) ?></code></td><td><?= (int)$c['is_active']===1?'Đang bật':'Đã tắt' ?></td><td class="text-right"><form method="post" action="<?= e(url('/admin/categories/'.(int)$c['id'].'/toggle')) ?>"><input type="hidden" name="_token" value="<?= e(Session::csrfToken()) ?>"><input type="hidden" name="active" value="<?= (int)$c['is_active']===1?'0':'1' ?>"><button class="btn btn-sm btn-outline-<?= (int)$c['is_active']===1?'danger':'success' ?>"><?= (int)$c['is_active']===1?'Tắt':'Bật' ?></button></form></td></tr><?php endforeach;?></tbody></table></div></div></div></div>
